import{_ as a,a0 as p,w as d,s as i,I as t,x as n,a1 as s,A as r,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"命令列星期二——第七部分 | LCTT x X-CMD","titleTemplate":false,"description":"命令列星期二——第七部分 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列星期二——第七部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列星期二——第七部分 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140807 Command Line Tuesdays--Part Seven","title":"命令列星期二——第七部分","tag":"201408","desc":""},"relativePath":"201408/20140807 Command Line Tuesdays--Part Seven.md","filePath":"[post].md"}'),u={name:"201408/20140807 Command Line Tuesdays--Part Seven.md"};function m(g,e,f,T,x,h){const o=p("Link");return d(),i("div",null,[e[16]||(e[16]=t("h1",{id:"命令列星期二——第七部分",tabindex:"-1"},[n("命令列星期二——第七部分 "),t("a",{class:"header-anchor",href:"#命令列星期二——第七部分","aria-label":"Permalink to “命令列星期二——第七部分”"},"​")],-1)),e[17]||(e[17]=t("p",null,[n("嗨，極客們，我已經檢查了我們的課程，今天我們在八章課程裏的第七部分。這就是説下週二我們還有一次課程，但也是最後一次“命令列星期二”課程。所以，今天，我們討論一些關於"),t("strong",null,"權限"),n("的問題！")],-1)),t("p",null,[e[1]||(e[1]=n("眾所周知，一台機器可能會有多名用户共同使用。為了保證用户之間互不干擾，就需要分配不同的權限。我們已經討論了文件權限的問題，你可以輕輕",-1)),s(o,{href:"1"},{default:r(()=>[...e[0]||(e[0]=[n("點此",-1)])]),_:1}),e[2]||(e[2]=n("回顧一下：",-1))]),e[18]||(e[18]=l(`<p><img src="http://linuxcommand.org/images/file_permissions.png" alt=""></p><h3 id="chmod" tabindex="-1">chmod <a class="header-anchor" href="#chmod" aria-label="Permalink to “chmod”">​</a></h3><p><strong>chmod</strong>命令被用來修改目錄或者文件的權限。為了修改權限，首先你得輸入chmod命令，之後你得輸入規範的權限修改，然後你就可以把目錄或者文件的權限修改成你想要的。這可以採用多種方式完成，但是肖茨先生喜歡八進制表示法。</p><p>把權限想像成一系列的位，每一個不為空的權限槽就是1，空的權限槽就是0。舉個例子：</p><pre><code>rwx = 111

rw- = 110
</code></pre><p>等等</p><p>看一下二進制表示法：</p><pre><code>rwx = 111 --&gt; in binary = 7

rw- = 110 --&gt; in binary = 6
 
r-x = 101 --&gt; in binary = 5
 
r– = 100 --&gt; in binary = 4
</code></pre><p>現在，如果你想把一個文件的權限改為：文件所有者和文件所有組擁有讀，寫，執行權限，但是其他用户沒有該文件任何權限，我們可以這樣做：</p><pre><code>chmod 770 example_file
</code></pre><h3 id="su-和-sudo" tabindex="-1">su 和 sudo <a class="header-anchor" href="#su-和-sudo" aria-label="Permalink to “su 和 sudo”">​</a></h3><p>有些時候普通用户需要成為超級用户，這樣才能完成一些任務（通常是一些安裝軟件任務）。為了暫時的獲取超級用户權限，我們可以使用<strong>su</strong>程序，輸入：</p><pre><code>su
</code></pre><p>輸入你的超級用户密碼，你就成為超級用户了。但是，警告：別忘記用一會之後（不需要的話）就退出超級用户模式。</p><p>在openSUSE和Ubuntu也其它的一些可選工具，它叫做sudo，sudo只是在某些方面和su不同，它是分配給制定用户的特殊命令，不像su，你可以用你自己用户的密碼執行sudo，而不需要超級用户密碼，舉個例子：</p><pre><code>sudo zypper in goodiegoodie
</code></pre><h3 id="修改文件和組所有權" tabindex="-1">修改文件和組所有權 <a class="header-anchor" href="#修改文件和組所有權" aria-label="Permalink to “修改文件和組所有權”">​</a></h3><p>想要改變文件的所有者，你可以在超級用户模式下運行<strong>chown</strong>，舉個例子，如果我想把文件的所有權從‘nenad’改為‘suse’，我可以這樣做：</p><pre><code>su

[輸入密碼]

chown suse example_file
</code></pre><p>同樣地，我也可以改變組的所有權，使用稍有不同的<strong>chgrp</strong>命令，很簡單：</p><pre><code>chgrp suse_group example_file
</code></pre><h3 id="下一次" tabindex="-1">下一次 <a class="header-anchor" href="#下一次" aria-label="Permalink to “下一次”">​</a></h3><p>正如我所闡述的，下一次我們就會結束這個系列。在此之後，相信你會做出自己的選擇，和我一起徜徉在終端的黑暗之中，只有一個綠色的閃爍光標作為燈塔。在那之前，極客們，記住</p><p>....享受更多的樂趣！</p><hr>`,25)),t("p",null,[e[4]||(e[4]=n("via: ",-1)),s(o,{href:"https://news.opensuse.org/2014/08/05/command-line-tuesdays-part-seven/"},{default:r(()=>[...e[3]||(e[3]=[n("https://news.opensuse.org/2014/08/05/command-line-tuesdays-part-seven/",-1)])]),_:1})]),t("p",null,[e[8]||(e[8]=n("作者：",-1)),s(o,{href:"https://news.opensuse.org/author/holden87/"},{default:r(()=>[...e[5]||(e[5]=[n("Nenad Latinović",-1)])]),_:1}),e[9]||(e[9]=n(" 譯者：",-1)),s(o,{href:"https://github.com/su-kaiyao"},{default:r(()=>[...e[6]||(e[6]=[n("su-kaiyao",-1)])]),_:1}),e[10]||(e[10]=n(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:r(()=>[...e[7]||(e[7]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=n("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[11]||(e[11]=[n("LCTT",-1)])]),_:1}),e[14]||(e[14]=n(" 原創翻譯，",-1)),s(o,{href:"http://linux.cn/"},{default:r(()=>[...e[12]||(e[12]=[n("Linux中國",-1)])]),_:1}),e[15]||(e[15]=n(" 榮譽推出",-1))])])}const L=a(u,[["render",m]]);export{y as __pageData,L as default};
